; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcmin (Amstrad CPC - minimal firmware (own screen and keys, firmware for discs and ROMs)), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 only when the library itself is built as a ROM (ntcRomAsm)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen

			; main.bas 6: If System.HasCapability("COMMANDLINE") Then
			dw fn_system_hascapability, str0, var_system_hascapability_hascapability
			dw kw_goto_ifzero_n, var_system_hascapability_hascapability, if1_1

			; main.bas 7: cl = System.CommandLine
			dw p_system_commandline_c
			dw kw_strcpy, var_cl, var_system_commandline_commandline

			; main.bas 8: Print "Command line: ["; cl; "]"
			dw kw_printzoscii
			dw glyph_43, glyph_6F, glyph_6D, glyph_6D, glyph_61, glyph_6E, glyph_64, glyph_20
			dw glyph_6C, glyph_69, glyph_6E, glyph_65, glyph_3A, glyph_20, glyph_5B, 0		; "Command line: ["
			dw kw_printstrvar, var_cl
			dw kw_printzoscii
			dw glyph_5D, 1, 0		; "]\n"

			; main.bas 9: Else
			dw if1_e_go
if1_1:

			; main.bas 10: Input "No command line here - type one"; cl
			dw kw_printzoscii
			dw glyph_4E, glyph_6F, glyph_20, glyph_63, glyph_6F, glyph_6D, glyph_6D, glyph_61
			dw glyph_6E, glyph_64, glyph_20, glyph_6C, glyph_69, glyph_6E, glyph_65, glyph_20
			dw glyph_68, glyph_65, glyph_72, glyph_65, glyph_20, glyph_2D, glyph_20, glyph_74
			dw glyph_79, glyph_70, glyph_65, glyph_20, glyph_6F, glyph_6E, glyph_65, glyph_3F
			dw glyph_20, 0		; "No command line here - type one? "
			dw kw_inputstr, var_cl

			; main.bas 11: End If
if1_e:

			; main.bas 13: w = 0
			dw kw_ztov, var_w

			; main.bas 14: For i = 1 To Len(cl)
			dw kw_ltov, 1, var_i
			dw kw_strlen, var_cl, for2_l
			dw kw_forupv_n, var_i, for2_l, for2_e
for2_t:

			; main.bas 15: If Mid$(cl, i, 1) <> " " Then
			dw kw_strmid, stmp0, var_cl, var_i, lit_1
			dw kw_strcmpne, stmp0, str1
			dw kw_goto_iffalse_n, if3_1

			; main.bas 16: If (i = 1) Or (Mid$(cl, i - 1, 1) = " ") Then w = w + 1 : Print w; ": ";
			dw kw_cpeqvl, var_i, 1
			dw kw_ftov, tmp0
			dw kw_addl, var_i, -1, tmp2
			dw kw_strmid, stmp1, var_cl, tmp2, lit_1
			dw kw_strcmpeq, stmp1, str1
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if4_1
			dw kw_inc, var_w
			dw kw_printint, var_w
			dw kw_printzoscii
			dw glyph_3A, glyph_20, 0		; ": "
if4_1:

			; main.bas 17: Print Mid$(cl, i, 1);
			dw kw_strmid, stmp0, var_cl, var_i, lit_1
			dw kw_printstrvar, stmp0

			; main.bas 18: If (i = Len(cl)) Or (Mid$(cl, i + 1, 1) = " ") Then Print
			dw kw_strlen, var_cl, tmp1
			dw kw_cpeqvv, var_i, tmp1
			dw kw_ftov, tmp0
			dw kw_addl, var_i, 1, tmp2
			dw kw_strmid, stmp1, var_cl, tmp2, lit_1
			dw kw_strcmpeq, stmp1, str1
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if5_1
			dw kw_printnl
if5_1:

			; main.bas 19: End If
if3_1:

			; main.bas 20: Next
			dw kw_next1v_n, var_i, for2_l, for2_t
for2_e:

			; main.bas 21: Print w; " words"
			dw kw_printint, var_w
			dw kw_printzoscii
			dw glyph_20, glyph_77, glyph_6F, glyph_72, glyph_64, glyph_73, 1, 0		; " words\n"

			; main.bas 22: Print "Files: "; IIf(System.HasCapability("FILES"), "yes", "no"); ", pages: "; IIf(System.HasCapability("PAGES"), "yes", "no")
			dw fn_system_hascapability, str2, var_system_hascapability_hascapability
			dw kw_vtov, var_system_hascapability_hascapability, tmp0
			dw kw_goto_ifzero_n, tmp0, ch6_0
			dw kw_strcpy, stmp0, str3
			dw ch6_e_go
ch6_0:
			dw kw_strcpy, stmp0, str4
			dw ch6_e_go
ch6_1:
			dw kw_strcpy, stmp0, str5
ch6_e:
			dw kw_printzoscii
			dw glyph_46, glyph_69, glyph_6C, glyph_65, glyph_73, glyph_3A, glyph_20, 0		; "Files: "
			dw kw_printstrvar, stmp0
			dw fn_system_hascapability, str6, var_system_hascapability_hascapability
			dw kw_vtov, var_system_hascapability_hascapability, tmp0
			dw kw_goto_ifzero_n, tmp0, ch7_0
			dw kw_strcpy, stmp0, str3
			dw ch7_e_go
ch7_0:
			dw kw_strcpy, stmp0, str4
			dw ch7_e_go
ch7_1:
			dw kw_strcpy, stmp0, str5
ch7_e:
			dw kw_printzoscii
			dw glyph_2C, glyph_20, glyph_70, glyph_61, glyph_67, glyph_65, glyph_73, glyph_3A
			dw glyph_20, 0		; ", pages: "
			dw kw_printstrvar, stmp0
			dw kw_printnl

			; main.bas 23: End
			dw kw_stop

; ============================================================
; function commandline (normal mode)
; ============================================================

p_system_commandline:

			; System.cls 80: CommandLine = ""
			dw kw_strcpy, var_system_commandline_commandline, str5
			dw p_system_commandline_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if1_e_go:			ld sp, if1_e
			jp ntc_xn
ch6_e_go:			ld sp, ch6_e
			jp ntc_xn
ch7_e_go:			ld sp, ch7_e
			jp ntc_xn

p_system_commandline_c:		; call commandline (normal)
			xor a
			ld (var_system_commandline_commandline), a
			ld (p_system_commandline_rs), sp
			ld sp, p_system_commandline
			jp ntc_xn
p_system_commandline_r:		; end of commandline
			ld sp, (p_system_commandline_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_system_hascapability:		; function hascapability (asm keyword), System.cls line 49
            pop hl		; System.cls 50
            pop de		; System.cls 51
            ld bc, fn_system_hascapability_caps		; System.cls 52
            jp ntc_capfind		; System.cls 53
fn_system_hascapability_caps:		; System.cls 54
            db "SCREEN", 0		; System.cls 55
            dw -1		; System.cls 56
            db "KEYBOARD", 0		; System.cls 57
            dw -1		; System.cls 58
            db "CLOCK", 0		; System.cls 59
            dw -1		; System.cls 60
            db "HOOK", 0		; System.cls 61
            dw -1		; System.cls 62
            db "INTERRUPTCLASSES", 0		; System.cls 63
            dw -1		; System.cls 64
            db "PAGES", 0		; System.cls 65
            dw -1		; System.cls 66
            db "FILES", 0		; System.cls 67
            dw -1		; System.cls 68
            db "ROMCOMMANDS", 0		; System.cls 69
            dw -1		; System.cls 70
            db "OVERLAYS", 0		; System.cls 71
            dw -1		; System.cls 72
            db 0		; System.cls 73
			ret			; end of #asm


; ============================================================
; Variables
; ============================================================

var_system_hascapability_hascapability:			dw 0
			db 40			; capacity
var_cl:			ds 41
			db 255			; capacity
var_system_commandline_commandline:			ds 256
var_w:			dw 0
var_i:			dw 0
for2_l:			dw 0
p_system_commandline_rs:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0
			db 255			; capacity
stmp0:			ds 256
			db 255			; capacity
stmp1:			ds 256

; numbers passed by address (read only)
lit_1:			dw 1

; ============================================================
; ZOSCII glyphs - each points at its 8 byte bitmap in ntc_font
; ============================================================

glyph_20			equ ntc_font + 0		; " "
glyph_2C			equ ntc_font + 96		; ","
glyph_2D			equ ntc_font + 104		; "-"
glyph_3A			equ ntc_font + 208		; ":"
glyph_3F			equ ntc_font + 248		; "?"
glyph_43			equ ntc_font + 280		; "C"
glyph_46			equ ntc_font + 304		; "F"
glyph_4E			equ ntc_font + 368		; "N"
glyph_5B			equ ntc_font + 472		; "["
glyph_5D			equ ntc_font + 488		; "]"
glyph_61			equ ntc_font + 520		; "a"
glyph_63			equ ntc_font + 536		; "c"
glyph_64			equ ntc_font + 544		; "d"
glyph_65			equ ntc_font + 552		; "e"
glyph_67			equ ntc_font + 568		; "g"
glyph_68			equ ntc_font + 576		; "h"
glyph_69			equ ntc_font + 584		; "i"
glyph_6C			equ ntc_font + 608		; "l"
glyph_6D			equ ntc_font + 616		; "m"
glyph_6E			equ ntc_font + 624		; "n"
glyph_6F			equ ntc_font + 632		; "o"
glyph_70			equ ntc_font + 640		; "p"
glyph_72			equ ntc_font + 656		; "r"
glyph_73			equ ntc_font + 664		; "s"
glyph_74			equ ntc_font + 672		; "t"
glyph_77			equ ntc_font + 696		; "w"
glyph_79			equ ntc_font + 712		; "y"

; ============================================================
; Strings
; ============================================================

str0:			db "COMMANDLINE", 0
str1:			db " ", 0
str2:			db "FILES", 0
str3:			db "yes", 0
str4:			db "no", 0
str5:			db 0
str6:			db "PAGES", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCMIN (NTCMIN.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_goto_ifzero_n:	jp 15
kw_forupv_n:	jp 25
kw_next1v_n:	jp 33
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_ftov:		jp 50
kw_inc:		jp 51
kw_addl:		jp 54
kw_orvv:		jp 74
kw_cpeqvv:	jp 95
kw_cpeqvl:	jp 96
kw_strcpy:	jp 122
kw_strlen:	jp 125
kw_strcmpeq:	jp 126
kw_strcmpne:	jp 127
kw_printzoscii:	jp 129
kw_printstrvar:	jp 130
kw_printint:	jp 132
kw_printnl:	jp 139
kw_inputstr:	jp 142
kw_scrinit:	jp 147
kw_strmid:	jp 174
ntc_capfind:	jp 243
ntc_plat_irqon:	jp 316
NTC_RJ_N	equ 28		; entries
ntc_csp	equ #8800		; ROM data
ntc_font	equ #948E		; ROM bss
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #897F		; ROM data
ntc_v_romen	equ #8985		; ROM data
ntc_v_romold	equ #8987		; ROM data
ntc_v_stamp	equ #8983		; ROM data
ntc_v_start	equ #8981		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM in slots 0 - 31, have it patch the jump block. NC = ready;
; C = not there / too old (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, c				; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot; C: DE = a number it hasn't got
			jr c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld hl, ntc_rj_tlk
			or a
			sbc hl, de			; (DE: past the message shown)
			jr nz, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_sig:		db "NTC", 1, "CPCMIN", 0	; the ROM's NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCMIN (NTCMIN.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCMIN too old: no routine #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "CMDLINE.BIN", ntc_start, ntc_end - ntc_start, ntc_start
